scanSensitivePath = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    println("敏感路径扫描开始: " + url)

    // 解析请求和URL
    freq, err = fuzz.HTTPRequest(req, fuzz.https(isHttps))
    if err != nil {
        println("解析请求失败: " + err)
        return
    }

    host, port, _ = str.ParseStringToHostPort(url)
    addr = str.HostPort(host, port)
    basePath = poc.GetHTTPRequestPath(req)

    // 去重机制
    pathIdentifier = addr + basePath
    pathIdentifier = codec.Md5(pathIdentifier)

    if db.GetProjectKey(pathIdentifier) == "scanned" {
        println("该路径已扫描，跳过: " + basePath)
        return
    } else {
        db.SetProjectKey(pathIdentifier, "scanned")
        println("开始扫描新路径: " + basePath)
    }

    // 提取基础URL (不含路径参数)
    baseURL = ""
    if isHttps {
        baseURL = "https://" + addr
    } else {
        baseURL = "http://" + addr
    }

    // 解析基本路径，确定目录
    pathParts = str.Split(basePath, "/")
    // 去除最后一个元素(可能是文件名)
    baseDirectory = ""
    if len(pathParts) > 1 {
        pathParts = pathParts[0:len(pathParts)-1]
        baseDirectory = str.Join(pathParts, "/")
        if !str.HasSuffix(baseDirectory, "/") {
            baseDirectory += "/"
        }
    } else {
        baseDirectory = "/"
    }

    // 定义敏感路径和相应的检测规则
    sensitivePathRules = [
        // Swagger相关
        {
            "path": "swagger-ui.html",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"swagger-ui.css\" || resp_body=\"swagger-ui.js\" || title=\"Swagger UI\")",
            "description": "Swagger UI",
            "severity": "medium"
        },
        {
            "path": "swagger-ui/index.html",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"swagger-ui.css\" || resp_body=\"swagger-ui.js\" || title=\"Swagger UI\")",
            "description": "Swagger UI",
            "severity": "medium"
        },
        {
            "path": "swagger/index.html",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"swagger-ui.css\" || resp_body=\"swagger-ui.js\" || title=\"Swagger UI\")",
            "description": "Swagger UI",
            "severity": "medium"
        },
        {
            "path": "swagger-resources",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"swaggerVersion\\\"\" || resp_body=\"\\\"location\\\"\")",
            "description": "Swagger Resources",
            "severity": "medium"
        },
        {
            "path": "api/swagger-resources",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"swaggerVersion\\\"\" || resp_body=\"\\\"location\\\"\")",
            "description": "Swagger Resources",
            "severity": "medium"
        },
        {
            "path": "v1/swagger.json",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"swagger\\\":\" || resp_body=\"\\\"swaggerVersion\\\"\" || resp_body=\"\\\"openapi\\\":\")",
            "description": "Swagger",
            "severity": "medium"
        },
        {
            "path": "v2/swagger.json",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"swagger\\\":\" || resp_body=\"\\\"swaggerVersion\\\"\" || resp_body=\"\\\"openapi\\\":\")",
            "description": "Swagger",
            "severity": "medium"
        },
        {
            "path": "swagger.json",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"swagger\\\":\" || resp_body=\"\\\"swaggerVersion\\\"\" || resp_body=\"\\\"openapi\\\":\")",
            "description": "Swagger",
            "severity": "medium"
        },
        {
            "path": "v2/api-docs",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"swagger\\\":\" || resp_body=\"\\\"openapi\\\":\")",
            "description": "Swagger API Doc",
            "severity": "medium"
        },
        {
            "path": "v3/api-docs",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"swagger\\\":\" || resp_body=\"\\\"openapi\\\":\")",
            "description": "Swagger API Doc",
            "severity": "medium"
        },
        {
            "path": "api/v2/api-docs",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"swagger\\\":\" || resp_body=\"\\\"openapi\\\":\")",
            "description": "Swagger API Doc",
            "severity": "medium"
        },

        // Spring相关
        {
            "path": "env",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"java.version\" || resp_body=\"os.arch\")",
            "description": "Spring Actuator Env",
            "severity": "high"
        },
        {
            "path": "actuator/env",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"java.version\" || resp_body=\"os.arch\")",
            "description": "Spring Actuator Env",
            "severity": "high"
        },
        {
            "path": "actuator",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"health\" || resp_body=\"{\\\"self\\\":{\" || resp_body=\"{\\\"_links\\\":{\" || resp_header=\"application/vnd.spring-boot.actuator\")",
            "description": "Spring Actuator",
            "severity": "medium"
        },
        {
            "path": "api/actuator",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"\\\"health\" || resp_body=\"{\\\"self\\\":{\" || resp_body=\"{\\\"_links\\\":{\" || resp_header=\"application/vnd.spring-boot.actuator\")",
            "description": "Spring Actuator",
            "severity": "medium"
        },
        {
            "path": "jolokia/list",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"springframework\" || resp_body=\"reloadByURL\" || resp_body=\"createJNDIRealm\")",
            "description": "Spring Jolokia",
            "severity": "high"
        },
        {
            "path": "actuator/jolokia/list",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"springframework\" || resp_body=\"reloadByURL\" || resp_body=\"createJNDIRealm\")",
            "description": "Spring Jolokia",
            "severity": "high"
        },

        // Tomcat相关
        {
            "path": "examples/servlets/servlet/SessionExample",
            "method": "GET",
            "checkType": "complex",
            "pattern": "title=\"Sessions Example\" || (resp_body=\"../sessions.html\" && resp_body=\"SessionExample;\")",
            "description": "Tomcat Session Example",
            "severity": "medium"
        },
        {
            "path": "manager/html",
            "method": "GET",
            "checkType": "complex",
            "pattern": "title=\"401 Unauthorized\" || title=\"403 Access Denied\" || (resp_body=\"manager-gui\" && resp_body=\"s3cret\")",
            "description": "Tomcat Manager App",
            "severity": "high"
        },

        // 代码仓库泄露
        {
            "path": ".git/config",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && resp_body=\"repositoryformatversion\"",
            "description": "Git 仓库信息泄露",
            "severity": "high"
        },
        {
            "path": ".svn/entries",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && ((resp_body=\"\\ndir\\n\" && resp_body=\"\\nfile\\n\") || resp_body==\"12\\n\")",
            "description": "SVN 仓库信息泄露",
            "severity": "high"
        },
        {
            "path": ".DS_Store",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && resp_body=\"\\x00\\x00\\x00\\x01\\x42\\x75\\x64\\x31\"",
            "description": "macOS 目录结构文件泄露",
            "severity": "low"
        },

        // 其他敏感路径
        {
            "path": "nacos/v1/console/server/state",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && resp_body=\"\\\"auth_enabled\\\":\\\"false\\\"\"",
            "description": "Nacos 配置中心",
            "severity": "high"
        },
        {
            "path": "druid/index.html",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && title==\"Druid Stat Index\"",
            "description": "Alibaba Druid",
            "severity": "medium"
        },
        {
            "path": "",
            "method": "GET",
            "checkType": "complex",
            "pattern": "resp_body=\"<ListBucketResult \" && resp_body=\"<?xml \"",
            "description": "S3 Bucket Listing",
            "severity": "medium"
        },
        {
            "path": "metrics",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && resp_body=\"# HELP node_uname_info\" && resp_body=\"# TYPE node_uname_info gauge\"",
            "description": "Metrics",
            "severity": "medium"
        },
        {
            "path": "services",
            "method": "GET",
            "checkType": "complex",
            "pattern": "status_code=\"200\" && (resp_body=\"Available SOAP services:\" || resp_body=\"Available Services:\") && resp_body=\"?wsdl\"",
            "description": "WSDL Service",
            "severity": "medium"
        }
    ]

    // 创建并发控制
    maxConcurrent = 10
    wg = sync.NewSizedWaitGroup(maxConcurrent)

    // 生成目录列表进行扫描
    dirsToScan = []

    // 添加当前目录
    dirsToScan = append(dirsToScan, baseDirectory)

    // 添加根目录
    dirsToScan = append(dirsToScan, "/")

    // 去重目录
    uniqueDirs := make(map[string]bool) // 使用字符串为键，布尔值为值  // 使用JavaScript对象作为集合
    uniqueDirsArray = []

    for _, dir := range dirsToScan {
        if !uniqueDirs[dir] {
            uniqueDirs[dir] = true
            uniqueDirsArray = append(uniqueDirsArray, dir)
        }
    }

    println("将扫描以下目录:")
    for _, dir := range uniqueDirsArray {
        println("  - " + baseURL + dir)
    }

    // =================== 敏感路径扫描 ===================
    println("开始敏感路径扫描...")

    for _, dir := range uniqueDirsArray {
        for _, rule := range sensitivePathRules {
            wg.Add()

            // 修复：匿名函数的正确语法
            currentDir = dir      // 在闭包中使用变量
            currentRule = rule    // 在闭包中使用变量

            go func() {
                defer wg.Done()

                directory = currentDir
                scanRule = currentRule

                targetPath = directory + scanRule["path"]
                targetUrl = baseURL + targetPath

                // 规范化URL，移除多余的斜杠
                targetUrl = str.ReplaceAll(targetUrl, "//", "/")
                targetUrl = str.Replace(targetUrl, ":/", "://", 1)

                println("扫描: " + targetUrl)

                // 创建请求
                method = scanRule["method"]

                // 直接使用GET方法检查所有路径
                resp, err = http.Get(targetUrl)
                if err != nil {
                    println("请求失败: " + targetUrl + " - " + err)
                    return
                }

                // 检查响应
                isVulnerable = false

                if scanRule["checkType"] == "status" {
                    statusCode = sprintf("%d", resp.StatusCode)
                    if statusCode == scanRule["pattern"] {
                        isVulnerable = true
                    }
                } else if scanRule["checkType"] == "content" {
                    respBody = resp.Body()
                    if str.MatchAnyOfRegexp(respBody, scanRule["pattern"]) {
                        isVulnerable = true
                    }
                }

                // 如果找到敏感路径，生成告警
                if isVulnerable {
                    println("🎯 发现敏感路径: " + targetUrl)

                    // 构建风险报告的详情 - 使用JavaScript对象字面量
                    details = {
                        "url": targetUrl,
                        "path": targetPath,
                        "status_code": resp.StatusCode,
                        "content_length": len(resp.Body())
                    }

                    // 生成风险报告
                    risk.NewRisk(
                        host,
                        risk.title("敏感路径: " + scanRule["path"]),
                        risk.severity(scanRule["severity"]),
                        risk.typeVerbose("敏感路径泄露"),
                        risk.details(details),
                        risk.payload(scanRule["path"]),
                        risk.description(scanRule["description"]),
                        risk.solution("移除或限制访问该敏感路径，确保正确配置Web服务器的目录访问控制"),
                        risk.request(req),
                        risk.response(rsp)
                    )
                }
            }()
        }
    }

    // 等待所有扫描完成
    wg.Wait()
    println("敏感路径扫描完成: " + url)
}
swg = sync.NewSizedWaitGroup(50)
handleResult = func(r) {
    swg.Add()
    go func{
        defer swg.Done()
                defer func{
            err = recover()
            if err != nil {
                yakit.Error("handle result met error: %s", err)
            }
        }
        url = r.Url()
        body = r.ResponseBody()
        reqRaw = r.RequestRaw()
        rspRaw = r.ResponseRaw()
        ishttps = str.HasPrefix(url, "https")
        scanSensitivePath(ishttps, url, reqRaw, rspRaw, body)

    }
}
// # mirrorNewWebsite 每新出现一个网站，这个网站的第一个请求，将会在这里被调用！
mirrorNewWebsite = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
yakit.Info("开始准备进行爬虫：%v", url)
yakit.EnableWebsiteTrees(url)
res, err := crawler.Start(url, 
    crawler.maxDepth(3),// 爬取深度为3
    crawler.concurrent(10),// 并发数为10
    crawler.timeout(10),// 超时时间10秒
    crawler.disallowSuffix([".css", ".jpg", ".jpeg", ".png", ".gif", ".svg", ".woff", ".woff2", ".ttf", ".eot"]),
    crawler.jsParser(true),
    crawler.userAgent("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36")// 设置UA
)
if err != nil {
    yakit.Error(err.Error())
    die(err)
}
yakit.Info("正在获取结果")
for r := range res {
    try {
        rsp, err := r.Response()
        if err != nil {
            log.info("Met ERROR for %v: %v", r.Url(), err)
            continue
        }
        handleResult(r)
    } catch err {
        yakit.Error(err.Error())
    }
}
yakit.Info("爬虫执行结束，等待敏感路径发现执行结果",url)
swg.Wait()
yakit.Info("插件执行结束")
}

